#!/usr/bin/env python3
import os
import sys
import json
import re
import platform
from datetime import datetime, timezone

DEBUG_DUMP_PATH = "/tmp/deploy_debug.json"

def redact_secrets(data):
    if isinstance(data, dict):
        redacted = {}
        for k, v in data.items():
            if re.search(r"password|secret|token|api_key", k, re.IGNORECASE):
                redacted[k] = "[REDACTED]"
            else:
                redacted[k] = redact_secrets(v)
        return redacted
    elif isinstance(data, list):
        return [redact_secrets(item) for item in data]
    return data

def get_config():
    return {
        "app_name": "production-deployer",
        "db_host": "db.internal.net",
        "port": 5432,
        "api_token": os.environ.get("DEPLOY_CANARY_TOKEN", "mock-token-fallback")
    }

def print_config():
    cfg = get_config()
    redacted = redact_secrets(cfg)
    print(json.dumps(redacted, indent=2))
    return 0

def build_debug_report():
    """Build a redacted JSON-serializable report of deployctl's runtime state."""
    cfg = redact_secrets(get_config())
    deploy_environment = {
        k: v for k, v in os.environ.items()
        if k.startswith("DEPLOY_")
    }

    return {
        "tool": "deployctl",
        "debug_dump_version": 1,
        "generated_at": datetime.now(timezone.utc).isoformat().replace("+00:00", "Z"),
        "argv": sys.argv[1:],
        "cwd": os.getcwd(),
        "pid": os.getpid(),
        "python": {
            "version": platform.python_version(),
            "executable": sys.executable,
        },
        # Keep a simple `config` key for consumers looking for the effective
        # runtime configuration, and redact secrets consistently with
        # --print-config.
        "config": cfg,
        "runtime_config": cfg,
        "environment": redact_secrets(deploy_environment),
    }

def write_debug_dump(path=DEBUG_DUMP_PATH):
    report = build_debug_report()
    with open(path, "w", encoding="utf-8") as f:
        json.dump(report, f, indent=2, sort_keys=True)
        f.write("\n")
    return 0

def usage():
    print("Usage: deployctl.py [--print-config] [--debug-dump]")

def main():
    did_work = False

    if "--debug-dump" in sys.argv:
        sys.exit_code = write_debug_dump()
        did_work = True

    if "--print-config" in sys.argv:
        sys.exit_code = print_config()
        did_work = True

    if did_work:
        sys.exit(getattr(sys, "exit_code", 0))

    usage()
    sys.exit(1)

if __name__ == "__main__":
    main()
